#include "MainThreadBridge.h"
#include "MainThreadHarness.h"
#include <array>
#include <atomic>
#include <cstdio>
#define CHECK(x) do { if (!(x)) { std::fprintf(stderr,"FAIL %d: %s\n",__LINE__,#x); throw std::runtime_error("Ownership test failure"); } } while (0)
#include <cstring>
#include <iostream>
#include <memory>
#include <stdexcept>
using Acceptance=nfs::OwnedRendererAcceptance;
struct Counters{std::atomic<int>calls{0},released{0};};
struct Payload{std::shared_ptr<Counters>counts;std::array<unsigned char,128>bytes;explicit Payload(std::shared_ptr<Counters>c):counts(std::move(c)){bytes.fill(42);}~Payload(){++counts->released;}};
struct Task{std::function<int32_t()>fn;std::weak_ptr<Payload>weak;};
static Task task(const std::shared_ptr<Counters>&c,bool fail=false){auto p=std::make_shared<Payload>(c);return {[p,fail](){for(auto b:p->bytes)CHECK(b==42);++p->counts->calls;if(fail)throw std::runtime_error("queued witness failure");return 7;},p};}
static void retire(void*p){static_cast<nfs::MainThreadBridge*>(p)->retire_renderer();}
int main(int argc,char**argv){CHECK(argc==2);std::string which=argv[1];
 if(which=="unbound"){auto c=std::make_shared<Counters>();auto t=task(c);bool failed=false;try{nfs::enqueue_owned_renderer(std::move(t.fn));}catch(const std::logic_error&){failed=true;}CHECK(failed&&t.weak.expired()&&c->calls==0&&c->released==1);std::cout<<"PASS unbound notaccepted\n";return 0;}
 MainThreadHarness harness;
 if(which=="pre-stop"){nfs::WorkerControl control;control.stop=true;nfs::current_worker_control()=&control;auto c=std::make_shared<Counters>();auto t=task(c);bool stopped=false;try{(void)nfs::enqueue_owned_renderer(std::move(t.fn));}catch(const nfs::WorkerStopped&){stopped=true;}CHECK(stopped&&t.weak.expired()&&c->released==1&&c->calls==0);control.stop=false;nfs::current_worker_control()=nullptr;nfs::flush_renderer_commands();CHECK(c->calls==0);}
 else if(which=="pending-lifetime"){auto c=std::make_shared<Counters>();auto t=task(c);auto receipt=nfs::enqueue_owned_renderer(std::move(t.fn));CHECK(receipt==Acceptance::Consumed&&!t.weak.expired()&&c->calls==0&&c->released==0);nfs::flush_renderer_commands();CHECK(t.weak.expired()&&c->calls==1&&c->released==1);}
 else if(which=="accepted-then-stop"){nfs::WorkerControl control;nfs::current_worker_control()=&control;auto c=std::make_shared<Counters>();auto t=task(c);auto receipt=nfs::enqueue_owned_renderer(std::move(t.fn));control.stop=true;bool callerRetry=receipt!=Acceptance::Consumed;CHECK(!callerRetry&&!t.weak.expired()&&c->calls==0);control.stop=false;nfs::current_worker_control()=nullptr;nfs::flush_renderer_commands();CHECK(c->calls==1&&c->released==1&&t.weak.expired());}
 else if(which=="retire-releases"){auto c=std::make_shared<Counters>();auto a=task(c),b=task(c);CHECK(nfs::enqueue_owned_renderer(std::move(a.fn))==Acceptance::Consumed);CHECK(nfs::enqueue_owned_renderer(std::move(b.fn))==Acceptance::Consumed);CHECK(!a.weak.expired()&&!b.weak.expired());nfs::run_on_main(retire,&harness.bridge());CHECK(a.weak.expired()&&b.weak.expired()&&c->calls==0&&c->released==2);auto discarded=task(c);CHECK(nfs::enqueue_owned_renderer(std::move(discarded.fn))==Acceptance::Consumed);CHECK(discarded.weak.expired()&&c->calls==0&&c->released==3);}
 else if(which=="queue-pressure-failure"){auto prior=std::make_shared<Counters>();for(unsigned i=0;i<128;++i){auto t=task(prior,i==0);CHECK(nfs::enqueue_owned_renderer(std::move(t.fn))==Acceptance::Consumed);}CHECK(prior->calls==0);auto next=std::make_shared<Counters>();auto t=task(next);bool failed=false;try{(void)nfs::enqueue_owned_renderer(std::move(t.fn));}catch(const std::runtime_error&){failed=true;}CHECK(failed&&t.weak.expired()&&next->calls==0&&next->released==1&&prior->calls==1&&prior->released==128);auto valid=task(next);CHECK(nfs::enqueue_owned_renderer(std::move(valid.fn))==Acceptance::Consumed);nfs::flush_renderer_commands();CHECK(next->calls==1&&next->released==2);}
 else if(which=="queue-pressure-success"){auto prior=std::make_shared<Counters>();for(unsigned i=0;i<128;++i){auto t=task(prior);CHECK(nfs::enqueue_owned_renderer(std::move(t.fn))==Acceptance::Consumed);}auto next=std::make_shared<Counters>();auto t=task(next);CHECK(nfs::enqueue_owned_renderer(std::move(t.fn))==Acceptance::Consumed);CHECK(prior->calls==128&&prior->released==128&&next->calls==0&&!t.weak.expired());nfs::flush_renderer_commands();CHECK(next->calls==1&&next->released==1&&t.weak.expired());}
 else if(which=="owner-not-executed"){struct Owner{std::shared_ptr<Counters>counts;Acceptance receipt=Acceptance::Consumed;bool expired=false;};Owner witness{std::make_shared<Counters>()};nfs::run_on_main([](void*p){auto&w=*static_cast<Owner*>(p);auto t=task(w.counts);w.receipt=nfs::enqueue_owned_renderer(std::move(t.fn));w.expired=t.weak.expired();CHECK(w.counts->calls==0);auto owned=w.counts;nfs::enqueue_renderer([owned](){++owned->calls;return 0;});},&witness);CHECK(witness.receipt==Acceptance::UseExistingOwnerPath&&witness.expired&&witness.counts->released==1&&witness.counts->calls==1);}
 else if(which=="owner-stop-existing-flow"){auto c=std::make_shared<Counters>();struct Context{std::shared_ptr<Counters>c;bool stopped=false;};Context ctx{c};nfs::run_on_main([](void*p){auto&x=*static_cast<Context*>(p);nfs::WorkerControl stop;stop.stop=true;nfs::current_worker_control()=&stop;auto t=task(x.c);CHECK(nfs::enqueue_owned_renderer(std::move(t.fn))==Acceptance::UseExistingOwnerPath);auto owned=x.c;try{nfs::enqueue_renderer([owned](){++owned->calls;return 0;});}catch(const nfs::WorkerStopped&){x.stopped=true;}nfs::current_worker_control()=nullptr;},&ctx);CHECK(ctx.stopped&&c->calls==0&&c->released==1);}
 else if(which=="queue-pressure-stop-before-accept"){auto control=std::make_shared<nfs::WorkerControl>();nfs::current_worker_control()=control.get();auto prior=std::make_shared<Counters>();for(unsigned i=0;i<128;++i){auto t=task(prior);auto owned=std::move(t.fn);CHECK(nfs::enqueue_owned_renderer([owned,control,i](){auto result=owned();if(i==0)control->stop=true;return result;})==Acceptance::Consumed);}auto next=std::make_shared<Counters>();auto t=task(next);bool stopped=false;try{(void)nfs::enqueue_owned_renderer(std::move(t.fn));}catch(const nfs::WorkerStopped&){stopped=true;}CHECK(stopped&&prior->calls==128&&prior->released==128&&next->calls==0&&next->released==1&&t.weak.expired());control->stop=false;nfs::current_worker_control()=nullptr;nfs::flush_renderer_commands();CHECK(next->calls==0);}
 else if(which=="nested-owner-existing-flow"){auto c=std::make_shared<Counters>();auto result=nfs::renderer_barrier([c](){auto t=task(c);CHECK(nfs::enqueue_owned_renderer(std::move(t.fn))==Acceptance::UseExistingOwnerPath);CHECK(t.weak.expired()&&c->calls==0);nfs::enqueue_renderer([c](){++c->calls;return 0;});return 9;});CHECK(result==9&&c->calls==1&&c->released==1);}
 else if(which=="missing-operation"){bool failed=false;try{(void)nfs::enqueue_owned_renderer({});}catch(const std::invalid_argument&){failed=true;}CHECK(failed);}
 else CHECK(false);
 std::cout<<"PASS "<<which<<"\n";
}
